from pathlib import Path
import json,os,subprocess,datetime,time,base64
r=Path("/expt/diagnostics/e52_rope_table_gpu_v1")
assert json.loads(Path("/expt/builds/e52_rope_table_module_v1/finished.json").read_text())["exit_code"]==0
pre=json.loads(Path("/expt/00_control/sj10_preflight_p0.json").read_text());assert pre["gpu_free"] and time.time()-datetime.datetime.fromisoformat(pre["at"]).timestamp()<180
assert json.loads(Path("/expt/runs/p51_bit_gather_reverse_off_v1/sj10/result.json").read_text())["exit_codes"]==[0]*8
r.mkdir(exist_ok=False)
p=Path("/expt/scripts/validate_v41_rope_table_v1.py");assert not p.exists();p.write_bytes(base64.b64decode(''))
(r/"worker.py").write_text("from pathlib import Path\nimport json,os,subprocess,datetime,signal,time\nr=Path('/expt/diagnostics/e52_rope_table_gpu_v1');cfg=json.loads(Path('/expt/runs/p51_bit_gather_reverse_off_v1/sj10/role_config.json').read_text());env=dict(os.environ);env.update(cfg['ranks'][0]['environment']);env.update(LD_PRELOAD='',PYTHONPATH='/expt/builds/e52_rope_table_module_v1:/expt/scripts:/expt/repos/xllm-musa:/workspace/xllm-mt-main',MUSA_VISIBLE_DEVICES='0',MTHREADS_VISIBLE_DEVICES='0',OMP_NUM_THREADS='1',TVM_FFI_GPU_BACKEND='musa')\ncmd=['python3','/expt/scripts/validate_v41_rope_table_v1.py','--output',str(r/'result.json')]\nwith (r/'test.log').open('xb') as f:\n p=subprocess.Popen(cmd,env=env,stdout=f,stderr=subprocess.STDOUT);start=Path('/proc',str(p.pid),'stat').read_text().split()[21];(r/'child.json').write_text(json.dumps({'pid':p.pid,'start_ticks':start,'command':cmd}));timeout=False\n try:rc=p.wait(timeout=240)\n except subprocess.TimeoutExpired:\n  timeout=True;proc=Path('/proc',str(p.pid));assert proc.exists() and proc.joinpath('stat').read_text().split()[21]==start\n  p.terminate()\n  try:rc=p.wait(timeout=30)\n  except subprocess.TimeoutExpired:rc=None\n(r/'finished.json').write_text(json.dumps({'exit_code':rc,'timed_out':timeout,'remaining_pid':p.pid if rc is None else None,'at':datetime.datetime.now().astimezone().isoformat()}))\n")
with (r/"worker.log").open("xb") as f:p=subprocess.Popen(["python3",str(r/"worker.py")],stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
v={"pid":p.pid,"start_ticks":Path("/proc",str(p.pid),"stat").read_text().split()[21],"at":datetime.datetime.now().astimezone().isoformat()};(r/"job.json").write_text(json.dumps(v));print(json.dumps(v))
